    { id=18131, tab=2, tier=6, col=1, name="Lightwell", icon="Spell_Holy_SummonLightwell", maxRank=1, prereqTalent=18128, prereqPoints=30, wired=true, tooltip={ "Creates a holy Lightwell near the priest. Friendly targets can click the Lightwell to restore 800 health over 10 sec. Being attacked cancels the effect. Lightwell lasts for 3 min or 5 charges." }, grant={ [1]=724 }, localized={deDE={name="Lichtbrunnen", tooltip={ "Erschafft einen heiligen Lichtbrunnen in der Nähe des Priesters. Befreundete Ziele können den Lichtbrunnen anklicken, um im Verlauf von 10 Sek. 800 Gesundheit wiederherzustellen. Wird das Ziel angegriffen, endet der Effekt. Der Lichtbrunnen hält 3 Min. lang oder für 5 Aufladungen an." }}} },
    { id=18132, tab=3, tier=0, col=1, name="Spirit Tap", icon="Spell_Shadow_Requiem", maxRank=5, prereqTalent=0, prereqPoints=0, wired=true, tooltip={ "Gives you a 20% chance to gain a 100% bonus to your Spirit after killing a target that yields experience. For the duration, your Mana will regenerate at a 50% rate while casting. Lasts 15 sec.", "Gives you a 40% chance to gain a 100% bonus to your Spirit after killing a target that yields experience. For the duration, your Mana may regenerate at a 50% rate while casting. Lasts 15 sec.", "Gives you a 60% chance to gain a 100% bonus to your Spirit after killing a target that yields experience. For the duration, your Mana may regenerate at a 50% rate while casting. Lasts 15 sec.", "Gives you a 80% chance to gain a 100% bonus to your Spirit after killing a target that yields experience. For the duration, your Mana may regenerate at a 50% rate while casting. Lasts 15 sec.", "Gives you a 100% chance to gain a 100% bonus to your Spirit after killing a target that yields experience. For the duration, your Mana may regenerate at a 50% rate while casting. Lasts 15 sec." }, localized={deDE={name="Willensentzug", tooltip={ "Gewährt Euch nach dem Töten eines Ziels, das Erfahrung gewährt, eine Chance von 20%, einen Bonus von 100% auf Eure Willenskraft zu erhalten. Während der Wirkungsdauer regeneriert Euer Mana beim Zauberwirken mit einer Rate von 50%. Hält 15 Sek. lang an.", "Gewährt Euch nach dem Töten eines Ziels, das Erfahrung gewährt, eine Chance von 40%, einen Bonus von 100% auf Eure Willenskraft zu erhalten. Während der Wirkungsdauer kann Euer Mana beim Zauberwirken mit einer Rate von 50% regenerieren. Hält 15 Sek. lang an.", "Gewährt Euch nach dem Töten eines Ziels, das Erfahrung gewährt, eine Chance von 60%, einen Bonus von 100% auf Eure Willenskraft zu erhalten. Während der Wirkungsdauer kann Euer Mana beim Zauberwirken mit einer Rate von 50% regenerieren. Hält 15 Sek. lang an.", "Gewährt Euch nach dem Töten eines Ziels, das Erfahrung gewährt, eine Chance von 80%, einen Bonus von 100% auf Eure Willenskraft zu erhalten. Während der Wirkungsdauer kann Euer Mana beim Zauberwirken mit einer Rate von 50% regenerieren. Hält 15 Sek. lang an.", "Gewährt Euch nach dem Töten eines Ziels, das Erfahrung gewährt, eine Chance von 100%, einen Bonus von 100% auf Eure Willenskraft zu erhalten. Während der Wirkungsdauer kann Euer Mana beim Zauberwirken mit einer Rate von 50% regenerieren. Hält 15 Sek. lang an." }}} },
    { id=18133, tab=3, tier=0, col=2, name="Blackout", icon="Spell_Shadow_GatherShadows", maxRank=5, prereqTalent=0, prereqPoints=0, wired=true, tooltip={ "Gives your Shadow damage spells a 2% chance to stun the target for 3 sec.", "Gives your Shadow damage spells a 4% chance to stun the target for 3 sec.", "Gives your Shadow damage spells a 6% chance to stun the target for 3 sec.", "Gives your Shadow damage spells a 8% chance to stun the target for 3 sec.", "Gives your Shadow damage spells a 10% chance to stun the target for 3 sec." }, localized={deDE={name="Blackout", tooltip={ "Gewährt Euren Schattenschadenszaubern eine Chance von 2%, das Ziel 3 Sek. lang zu betäuben.", "Gewährt Euren Schattenschadenszaubern eine Chance von 4%, das Ziel 3 Sek. lang zu betäuben.", "Gewährt Euren Schattenschadenszaubern eine Chance von 6%, das Ziel 3 Sek. lang zu betäuben.", "Gewährt Euren Schattenschadenszaubern eine Chance von 8%, das Ziel 3 Sek. lang zu betäuben.", "Gewährt Euren Schattenschadenszaubern eine Chance von 10%, das Ziel 3 Sek. lang zu betäuben." }}} },
